"""Lab check for DAM document recognition: python3 references/score.py <file|model> <field>.

Compares one field of the trial's output.json with references/expected.json; exit 0 when it matches.
Names match without case, accents, punctuation or word order; aliases as sets; dates as ISO; sites by domain.
"""
import json, re, sys, unicodedata


def fold(s):
    s = unicodedata.normalize('NFKD', str(s)).encode('ascii', 'ignore').decode().lower()
    return sorted(w for w in re.split(r'[^a-z0-9]+', s) if w)


def aliases(v):
    if v is None:
        return set()
    items = v if isinstance(v, list) else re.split(r'[,;/]|\band\b', str(v))
    return {' '.join(fold(x)) for x in items if fold(x)}


def site(v):
    s = str(v or '').lower()
    m = re.search(r'([a-z0-9-]+\.example)', s)
    return m.group(1) if m else ' '.join(fold(s))


def same(field, want, got):
    if field in ('legal_name',):
        return got is not None and fold(want) == fold(got)
    if field == 'alias':
        return aliases(want) == aliases(got)
    if field == 'site':
        return site(want) == site(got)
    if field in ('signature', 'readable', 'name_variants'):
        return want is got
    if field in ('duplicates',):
        return {tuple(sorted(p)) for p in want} == {tuple(sorted(p)) for p in (got or []) if isinstance(p, list)}
    if field == 'unreadable':
        return set(want) == set(got or [])
    return want == got


def main():
    target, field = sys.argv[1], sys.argv[2]
    want = json.load(open('references/expected.json'))
    try:
        got = json.load(open('output.json'))
    except Exception as e:
        sys.exit('no output.json: %s' % e)
    if target == 'model':
        w, g = want['model'].get(field), (got.get('model') or {}).get(field)
    else:
        w = next(d for d in want['documents'] if d['file'] == target)[field]
        g = next((d for d in got.get('documents') or [] if isinstance(d, dict) and d.get('file') == target), {}).get(field)
    if not same(field, w, g):
        sys.exit('%s %s: expected %r, got %r' % (target, field, w, g))


main()
